from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any


@dataclass
class StateIR:
    name: str
    default: Any
    # When true, the field is mirrored to localStorage: its initial value is
    # restored on construct and every change is written back, so it survives
    # reloads (and navigation away and back).
    persist: bool = False

    def to_dict(self) -> dict[str, Any]:
        d = {"name": self.name, "default": self.default}
        if self.persist:
            d["persist"] = True
        return d


@dataclass
class StatementIR:
    type: str
    data: dict[str, Any]

    @staticmethod
    def _serialize(value: Any) -> Any:
        # A for_loop carries a nested list of StatementIR in data["body"].
        if isinstance(value, StatementIR):
            return value.to_dict()
        if isinstance(value, list):
            return [StatementIR._serialize(v) for v in value]
        if isinstance(value, dict):
            return {k: StatementIR._serialize(v) for k, v in value.items()}
        return value

    def to_dict(self) -> dict[str, Any]:
        return {
            "type": self.type,
            **{k: self._serialize(v) for k, v in self.data.items()},
        }


@dataclass
class MethodIR:
    name: str
    statements: list[StatementIR]
    # Local variables assigned inside an if/for block — hoisted to a `let`
    # declaration at the top of the method so the value survives the block.
    locals: list[str] = field(default_factory=list)
    # Positional parameters (besides self) — e.g. the value an on_change
    # handler receives. Currently at most one.
    params: list[str] = field(default_factory=list)
    # True for `async def` methods — compiled to an async JS method.
    is_async: bool = False

    def to_dict(self) -> dict[str, Any]:
        d: dict[str, Any] = {
            "name": self.name,
            "statements": [s.to_dict() for s in self.statements],
        }
        if self.locals:
            d["locals"] = list(self.locals)
        if self.params:
            d["params"] = list(self.params)
        if self.is_async:
            d["is_async"] = True
        return d


@dataclass
class WidgetIR:
    type: str
    props: dict[str, Any] = field(default_factory=dict)
    children: list[WidgetIR] = field(default_factory=list)

    @staticmethod
    def _serialize(value: Any) -> Any:
        # Props can nest a WidgetIR — e.g. a ListView builder body.
        if isinstance(value, WidgetIR):
            return value.to_dict()
        if isinstance(value, dict):
            return {k: WidgetIR._serialize(v) for k, v in value.items()}
        if isinstance(value, list):
            return [WidgetIR._serialize(v) for v in value]
        return value

    def to_dict(self) -> dict[str, Any]:
        d: dict[str, Any] = {"type": self.type}
        d.update({k: self._serialize(v) for k, v in self.props.items()})
        if self.children:
            d["children"] = [c.to_dict() for c in self.children]
        return d


@dataclass
class ComponentIR:
    """IR for a reusable ``Component`` subclass.

    Like an app but with ``props`` (the ``__init__`` parameter names) and no
    self-mount. ``states`` is empty for a stateless component.
    """

    name: str
    props: list[str]
    states: list[StateIR]
    methods: list[MethodIR]
    tree: WidgetIR
    # ``__init__`` body assignments — list of (field_name, value_ir). The
    # generated constructor binds the params then runs these, so overrides and
    # derived/computed props work (re-run on re-render via _applyProps).
    init: list = field(default_factory=list)
    # The ``*children`` parameter name, if the component takes a multi-child
    # slot — extra positional widgets at the call site collect into this list.
    variadic: "str | None" = None
    # Literal ``__init__`` parameter defaults (positional-with-default and
    # keyword-only alike): an omitted argument at a call site is filled from
    # here at compile time, matching Python's semantics.
    defaults: dict = field(default_factory=dict)
    # Keyword-only params (after ``*args``) — bound like props, but never bound
    # from a positional arg, so a `*sections, name=...` signature keeps every
    # positional in the variadic slot.
    kwonly: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "props": list(self.props),
            "kwonly": list(self.kwonly),
            "init": [[f, v] for f, v in self.init],
            "variadic": self.variadic,
            "state": [s.to_dict() for s in self.states],
            "methods": [m.to_dict() for m in self.methods],
            "tree": self.tree.to_dict(),
        }


@dataclass
class AppIR:
    name: str
    states: list[StateIR]
    methods: list[MethodIR]
    tree: WidgetIR
    # Reusable components referenced (transitively) by build(), emitted
    # alongside this app and deduped by name.
    components: "list[ComponentIR]" = field(default_factory=list)
    # Global store defaults (field -> default), when this app declares
    # ``store = Store(...)``. Emitted once as Workpeg.initStore at bootstrap.
    store: "dict[str, Any] | None" = None
    # pegment token overrides (--wp-<name> -> value) from ``theme = Theme(...)``.
    theme: "dict[str, str] | None" = None
    # Message catalogue from ``translations = Translations(...)`` — shaped
    # {"default": <lang>, "langs": {<lang>: {token: text}}}. Emitted once as
    # Workpeg.initLocale at bootstrap; consumed by the Locale widget.
    translations: "dict[str, Any] | None" = None
    # The document <title> for this page, from ``title = "..."`` (a plain string
    # — the only thing allowed to reach the title; never markup or code).
    title: "str | None" = None
    # Web-font stylesheet URLs from ``fonts = [...]`` — allowlisted to the Google
    # Fonts hosts and injected as <link> tags in the document head (head-only, so
    # they never reach the generated JS). See AppIR/RouterIR fonts threading.
    fonts: "list[str] | None" = None
    # The Peg's search representation from ``search_manifest = SearchManifest(...)``
    # — declared keys only ({label, link, icon}). build_ui emits it to
    # dist/manifest.json (never into the generated JS); the platform renders it
    # server-side per search hit. See ASTParser._parse_search_manifest_decl.
    search_manifest: "dict[str, str] | None" = None

    def to_dict(self) -> dict[str, Any]:
        d = {
            "name": self.name,
            "state": [s.to_dict() for s in self.states],
            "methods": [m.to_dict() for m in self.methods],
            "tree": self.tree.to_dict(),
            "components": [c.to_dict() for c in self.components],
        }
        if self.store is not None:
            d["store"] = self.store
        if self.theme is not None:
            d["theme"] = self.theme
        if self.translations is not None:
            d["translations"] = self.translations
        return d


@dataclass
class RouteIR:
    path: str
    app: AppIR
    # The persistent Shell this route renders inside, if any (its child Outlet
    # holds the routed app). Distinct shells are emitted once via RouterIR.shells.
    shell: "AppIR | None" = None

    def to_dict(self) -> dict[str, Any]:
        d: dict[str, Any] = {"path": self.path, "app": self.app.to_dict()}
        if self.shell is not None:
            d["shell"] = self.shell.name
        return d


@dataclass
class RouterIR:
    """IR for a multi-route SPA built from a ``Router`` subclass."""

    name: str
    routes: "list[RouteIR]"
    not_found: "AppIR | None" = None
    # Distinct Shell layout classes referenced by routes, deduped by name and
    # emitted once (like an App) so several routes can share one shell instance.
    shells: "list[AppIR]" = field(default_factory=list)
    # All components referenced by any route, emitted once, deduped by name.
    components: "list[ComponentIR]" = field(default_factory=list)
    # Global store defaults (field -> default) declared on the Router.
    store: "dict[str, Any] | None" = None
    # pegment token overrides (--wp-<name> -> value) from ``theme = Theme(...)``.
    theme: "dict[str, str] | None" = None
    # Message catalogue from ``translations = Translations(...)`` — shaped
    # {"default": <lang>, "langs": {<lang>: {token: text}}}.
    translations: "dict[str, Any] | None" = None
    # Web-font stylesheet URLs from ``fonts = [...]`` (allowlisted Google Fonts
    # hosts), injected as <link> tags in the document head.
    fonts: "list[str] | None" = None
    # The Peg's search representation from ``search_manifest = SearchManifest(...)``
    # — declared keys only. Emitted to dist/manifest.json, rendered server-side.
    search_manifest: "dict[str, str] | None" = None

    def to_dict(self) -> dict[str, Any]:
        d: dict[str, Any] = {
            "name": self.name,
            "routes": [r.to_dict() for r in self.routes],
            "components": [c.to_dict() for c in self.components],
        }
        if self.not_found is not None:
            d["not_found"] = self.not_found.to_dict()
        if self.store is not None:
            d["store"] = self.store
        if self.theme is not None:
            d["theme"] = self.theme
        return d
